  return function (ctx: any): Promise<void> {
    function dispatch(i: number): Promise<void> {
      if (i >= middlewares.length) return Promise.resolve();
      const fn = middlewares[i];
      return Promise.resolve(fn(ctx, () => dispatch(i + 1)));
    }
    return dispatch(0);
  };
}

