function checkRateLimit(key: string, now: number, windowMs: number, maxRequests: number, store: Map<string, number[]>): { allowed: boolean; remaining: number; retryAfterMs: number } {
  const timestamps = (store.get(key) || []).filter(t => t > now - windowMs);
  if (timestamps.length >= maxRequests) {
    store.set(key, timestamps);
    const retryAfterMs = (timestamps[0] + windowMs) - now;
    return { allowed: false, remaining: 0, retryAfterMs };
  }
  timestamps.push(now);
  store.set(key, timestamps);
  return { allowed: true, remaining: maxRequests - timestamps.length, retryAfterMs: 0 };
}

