function memoizeWithTtl<T>(fn: (arg: string) => Promise<T>, ttlMs: number): (arg: string, now?: number) => Promise<T> {
  const cache = new Map<string, { value: T; expiresAt: number }>();
  return async (arg: string, now: number = Date.now()): Promise<T> => {
    const entry = cache.get(arg);
    if (entry && now <= entry.expiresAt) {
      return entry.value;
    }
    const value = await fn(arg);
    cache.set(arg, { value, expiresAt: now + ttlMs });
    return value;
  };
}

