  return {
    register(fn: () => Promise<void>): void {
      cleanups.push(fn);
    },
    async shutdown(): Promise<number> {
      let count = 0;
      while (cleanups.length > 0) {
        const fn = cleanups.pop()!;
        await fn();
        count++;
